"""Two new books and character stories with per-quest, ordered NPC discussions."""
from collections import Counter

# Content below is authored as episodes so each conversation has its own reply.

def item(kind,target,count=1):
    verbs={'collect':'Hold','submit':'Donate','craft':'Craft','smelt':'Smelt','kill':'Defeat','visit':'Visit dimension','biome':'Discover biome','achieve':'Complete advancement'}
    return dict(type=kind,target='minecraft:'+target,count=count,label=f'{verbs[kind]}: {target.replace("_"," ")} ({count})')
def talk(npc,subject,response):
    return dict(type='talk',target='thedeepnightnpcs:'+npc,count=1,label=f'Discuss {subject} with {npc.replace("_"," ").title()}',dialogue=response)
def row(title,story,work,conversations,after):return (title,story,work,conversations,after)
def t(npc,subject,response):return talk(npc,subject,response)
def i(kind,target,count=1):return item(kind,target,count)

# Every chapter has two parallel enquiries followed by a reunion, then a conclusion.
BOOKS=[]
def chapter(book,code,title,rows,choice=None):
    assert len(rows)==6
    BOOKS.append((book,code,title,rows,choice or []))

chapter('Book IV | The Roads That Remember','rr_letter','XXI | The Courier without a Destination',[
row('A Petition in Clean Water','A courier reaches Eldara carrying a dry petition inside a soaked coat. The names on the envelope belong to a district the council has never supplied.',[i('collect','paper',8)],[t('rowan','the unlisted district','There is no district by that name in our ration ledger. That proves something about the ledger, not about the people. Ask Iona where the old river road ends.'),t('iona','the river road','The road ends on my map because that was where our escorts turned back. I mistook the limit of our protection for the limit of the world.')],'Eldara pins the petition beside the completed chronicle. The peace has a boundary nobody intended to draw.'),
row('The Ink That Washed Away','Sera suspects the damaged address was written over an older name. Eldara asks you to preserve both accounts before choosing which one to believe.',[i('collect','ink_sac',4)],[t('sera','the overwritten address','The upper ink is recent. Under it is a tax district abolished thirty years ago. The inhabitants kept living there after the treasury stopped counting them.')],'Two names remain legible on the copied petition; neither is crossed out.'),
row('Bootprints at the Ferry','Fen remembers collecting a family at an unofficial landing. The children called the river by a name he had never heard.',[i('craft','oak_boat')],[t('fen','the unofficial landing','We called it an empty bank because it had no tollhouse. People were waiting there with baskets. We sailed past a harbor we did not know how to recognize.')],'The ferry chart gains a landing described by its users, not by a royal survey.'),
row('Put Both Maps on the Table','The address and ferry account disagree about the boundary. Eldara wants the disagreement heard by the people who must deliver relief.',[i('craft','cartography_table')],[t('iona','the two maps','Fen navigates by crossings; the treasury navigated by charges. Lay one over the other and the missing district appears between the fees.'),t('rowan','the relief boundary','Then we change our delivery route. Nobody should need to prove that an old king wanted their taxes before we will share a meal.')],'The council authorizes a survey whose first instruction is to ask permission.'),
row('An Expedition with an Empty Seat','Tamsin refuses a survey party that carries instruments but no room for someone who needs to return with it.',[i('submit','bread',24),i('submit','white_wool',8)],[t('tamsin','the returning passenger','Leave one bed and one portion unassigned. An empty place can be preparation rather than waste. Tell Elian the escort is coming home with civilians.'),t('elian','the survey escort','Our orders are to protect the survey, not to make its witnesses agree. If they refuse us entry, we return with the refusal intact.')],'The party leaves with a seat for a person whose name is not yet known.'),
row('A Name Spoken at the Landing','The petitioners offer no royal seal. Eldara asks you to bring back a name spoken by someone who actually lives beside the water.',[],[t('fen','the river community','They call the settlement Reedbank. Write that first. The old district title can go underneath, if it helps someone find the right boat.'),t('rowan','Reedbank\'s petition','We can record Reedbank without claiming it. Ask what help they want, then ask what they wish us to leave alone.')],'REEDBANK: a place in the common ledger, with no ownership mark beside it.')])

chapter('Book IV | The Roads That Remember','rr_river','XXII | The Water Owes No Tribute',[
row('The Flood Marks above the Door','Eldara receives sketches of water lines inside homes far above the river. Tamsin thinks the damage began before the latest rain.',[i('collect','bucket',3)],[t('tamsin','the water marks','The patients describe three small floods before the large one. Each time they rebuilt a little lower because the dry ground had been fenced.'),t('fen','the blocked waterway','Three gates upstream were closed for a private mill. I cannot promise opening them fixes everything. We need the whole watercourse.')],'The survey begins upstream instead of blaming the people nearest the flood.'),
row('A Bank Is More than a Line','Iona wants observations from an actual riverbank before the council drafts its first repair order.',[i('biome','river')],[t('iona','the river survey','Mark places water can spread without taking a house with it. A narrow channel is easier to draw, but the river has never agreed to stay narrow.')],'The first sketch includes a floodplain, paths, gardens, and two places left deliberately open.'),
row('Who Sold the Dry Ground','Rowan has found deeds granting the same high field to three different owners. Sera needs a record that preserves the conflict.',[i('craft','writable_book',2)],[t('sera','the competing deeds','All three seals are authentic. The fraud was the promise that each seal made every earlier life on the land disappear.'),t('rowan','the disputed field','For the emergency shelter, use a temporary agreement with the families. A crisis should not settle ownership for the wealthiest claimant.')],'The shelter agreement expires when the emergency ends; nobody signs away a home.'),
row('The Price of a Closed Gate','Mara identifies a familiar hinge in the mill drawings. Jorge has seen replacements sold as military salvage.',[i('collect','iron_ingot',12)],[t('mara','the gate hinge','These fittings were designed to fail open. Someone added a locking pin, then charged the downstream villages whenever it was removed.'),t('jorge','the locking pins','I sold the pins as scrap, without knowing the contract. I kept the receipts. Take copies; a mistake is not a reason to destroy evidence.')],'The repair proposal becomes an investigation into the people being paid to delay it.'),
row('Ask the People below the Gate','Elian expects the owners to refuse inspection. Eldara insists that the plan first reach the people who live below it.',[i('submit','paper',24)],[t('fen','the downstream meeting','Carry the same drawing to each landing. They need to know what a controlled release means before anyone hears a heroic speech about breaking the gate.'),t('elian','the inspection order','We will escort engineers with witnesses from both banks. A sword can open a door and still make every useful conversation impossible.')],'The inspection party carries invitations beside its warrants.'),
row('A Temporary Right of Passage','Reedbank agrees to a supervised inspection. Eldara asks Rowan to record its conditions in language the inspectors cannot conveniently forget.',[],[t('rowan','the passage agreement','The community chooses its witnesses. No survey marker becomes a border. Any damage is repaired before the inspectors return home.'),t('mara','the inspection promise','Put my workshop on the repair line. An agreement is more credible when somebody has already set aside the materials to keep it.')],'The first compact is narrow, practical, and signed by people who will see one another again.')])

chapter('Book IV | The Roads That Remember','rr_gates','XXIII | A Machine Built to Wait',[
row('The Keeper\'s Missing Instructions','Inside the recovered maintenance folio, Eldara finds repair diagrams followed by blank pages where public warnings should have been.',[i('collect','redstone',16)],[t('mara','the blank warning pages','The mechanism is ordinary engineering. What is missing is the duty to tell people before moving the water. A silent gate is cheaper for its owner.'),t('sera','the maintenance folio','The pages were removed after the diagrams were copied. We should find who kept the second copy, rather than inventing what we wish it said.')],'The investigation follows the missing warning, not a mythical machine curse.'),
row('A Signal That Can Be Checked','Mara asks for a small model of the warning circuit, with every connection visible to an apprentice.',[i('craft','repeater',4),i('craft','redstone_lamp',2)],[t('mara','the warning model','A lit lamp means a gatekeeper has announced a change. It does not mean the river is safe. Write that distinction where everyone can read it.')],'The model becomes a teaching tool instead of a new source of authority.'),
row('The Copy in the Tool Chest','Jorge finds a water-stained manual among a former gatekeeper\'s tools. Sera asks you to preserve it without cleaning away the handwritten objections.',[i('collect','book',4)],[t('jorge','the gatekeeper\'s tools','She kept a list of villages to warn. Somebody later wrote that the list was outside her duties. She kept warning them until they dismissed her.'),t('sera','the handwritten objections','The margins tell us who tried to keep this machine humane. We will copy them at the same size as the official instructions.')],'The next edition gives the dismissed gatekeeper\'s notes their own heading.'),
row('A Warning with a Return Signal','Iona sees a problem with a one-way alarm: isolated landings might hear it after the water arrives.',[i('craft','comparator',2)],[t('iona','the return signal','Let each landing answer that its boats are clear. Silence must mean wait, not permission. Otherwise the farthest people pay for our efficiency.'),t('fen','the harbor acknowledgement','Give the smallest ferry the same right to delay a release as the largest warehouse. It has fewer passengers, not less valuable ones.')],'The protocol waits for the slowest landing.'),
row('Practice without Raising the River','Eldara orders a rehearsal using lamps and written reports. Elian prepares a rescue exercise instead of an audience.',[i('submit','torch',32),i('submit','oak_boat',3)],[t('elian','the rehearsal','Every team gets to call a halt. We will practice carrying somebody home, not congratulating ourselves for assuming nobody falls.'),t('tamsin','the rescue station','Put dry blankets beside the demonstration. People remember the lesson better when needing help does not become a public embarrassment.')],'The first rehearsal is stopped twice. Mara calls both interruptions successes.'),
row('The Test That Was Allowed to Fail','A missed acknowledgement exposes a weakness in the model. Eldara asks the team to keep the failed test in the public record.',[],[t('mara','the failed test','Do not polish this into a tale of flawless engineers. The interruption found the mistake while it was still only a lamp.'),t('rowan','the public record','The budget will include another rehearsal. If we fund only successful demonstrations, we teach people to hide the useful ones.')],'The common works ledger opens with an error and the cost of correcting it.')])

chapter('Book IV | The Roads That Remember','rr_fleet','XXIV | The Cargo Nobody Counted',[
row('Ships Arriving Empty','Fen reports boats returning with empty holds despite signed delivery receipts. Eldara asks you to compare the promises with the actual meals.',[i('collect','paper',16)],[t('fen','the empty holds','The crews delivered everything on their manifests. The manifests themselves were shortened at the bonded warehouse. Blaming the sailors would be convenient.'),t('tamsin','the missing meals','The pantry has been stretching portions for six days. Nobody complained because each household thought another household needed the food more.')],'Eldara orders immediate supplies while the investigation continues.'),
row('Food before an Explanation','The relief kitchen needs a delivery now. Its patients cannot eat a promise that the accounts will eventually be corrected.',[i('submit','baked_potato',48)],[t('tamsin','the emergency kitchen','Thank you. We will serve the meal before asking anyone for testimony. Hunger can make a witness agree with whoever holds the ladle.')],'The kitchen separates its serving tables from the investigators\' desks.'),
row('The Duplicate Receipt','Sera discovers identical cargo numbers on shipments supposedly bound for opposite banks.',[i('craft','writable_book',3)],[t('sera','the duplicated receipt','The second receipt carries a warehouse fee for goods that never passed through its doors. The missing food became a charge before it became a shortage.'),t('jorge','the warehouse stamp','I recognize the stamp maker\'s work. The mark is real; the claim is false. Keep asking what a document does, not just whether it looks authentic.')],'The evidence points to the Ledger House, a consortium surviving the fall of the royal court.'),
row('The Cost of Keeping Quiet','A witness fears losing passage if the warehouse owners learn they spoke. Iona proposes a route with several safe returns.',[i('craft','compass')],[t('iona','the witness route','No secret tunnel, no miraculous escape. Three ordinary hosts who know the next host, and a boat that can turn back at every stage.'),t('fen','the witness passage','I will reserve places without publishing the passengers. Public spending needs an account; endangered people do not need a public itinerary.')],'The witness agrees to speak when the route home is explained first.'),
row('A Hold Reserved for Repairs','Mara argues that relief voyages fail when every departure is full and no boat can carry broken equipment home.',[i('submit','iron_ingot',24),i('submit','oak_planks',48)],[t('mara','the repair cargo','A full outbound hold looks impressive on a report. Leave space on the return. Broken pumps and exhausted people also need passage.'),t('fen','the return manifest','The next manifest lists room kept empty for emergencies. I expect the accountants to object. They can help load it.')],'The fleet begins measuring successful returns alongside delivered weight.'),
row('A Fleet outside the Warehouse','The captains agree to bypass the Ledger House for emergency relief. Eldara asks how to keep that emergency power from becoming permanent.',[],[t('rowan','the emergency charter','Set a date for review and publish the costs. Necessary action should leave behind a way to end itself.'),t('fen','the captains\' charter','Every captain signs the same limit. We are opening a route, not founding another house that owns the river.')],'The emergency fleet departs under a charter with an ending written into it.')])

chapter('Book IV | The Roads That Remember','rr_quarry','XXV | Stone for the Common Works',[
row('A Wall That Leans Downstream','The survey locates a damaged retaining wall. Mara refuses to estimate repairs from the tidy outline in the warehouse plan.',[i('collect','stone',32)],[t('mara','the retaining wall','Someone drew the face of the wall and left out its foundations. We need to know what carries the weight before adding anything to it.'),t('iona','the wall approaches','There are two routes to inspect it. One crosses a working garden; ask its keeper before calling it the convenient route.')],'The repair schedule begins with consent and a foundation survey.'),
row('The Quarry\'s Quiet Shift','Elian reports that quarry workers stopped ringing the change-of-shift bell because the sound attracted nearby dead.',[i('kill','zombie',24)],[t('elian','the quarry watch','We can protect the shift change. We cannot ask workers to keep silent forever because we find patrols inconvenient.'),t('caelen','the quarry threat','Watch the approach routes, not just the kill count. A cleared path needs someone assigned to notice when it becomes dangerous again.')],'A regular watch replaces a dangerous custom nobody had meant to make permanent.'),
row('What the Stone Is Worth','Jorge sees the proposed stone price triple after the common works announcement. He offers his old invoices for comparison.',[i('collect','emerald',12)],[t('jorge','the stone invoices','The old price barely paid the cutters. The new price barely reaches them. Ask where the difference goes before calling either price fair.'),t('rowan','the workers\' payment','Then the contract names the workers\' share and the delivery costs separately. A low public price is not a victory if someone else absorbs the injury.')],'The procurement contract gains a line for wages the council can actually inspect.'),
row('The Mason\'s Practical Objection','Mara asks for a model that shows drainage gaps. Rowan wants to know why the wall must deliberately admit water.',[i('craft','stone_bricks',64)],[t('mara','the drainage gaps','Because holding every drop back puts the whole hillside behind the wall. Some strength comes from allowing a pressure to pass.'),t('rowan','the revised design','Keep the explanation with the model. Otherwise a future steward will spend good money filling the gaps to make it look finished.')],'The model remains visibly imperfect in a way that can be explained.'),
row('No Work without a Way Home','Tamsin finds workers sleeping beside the stone stacks to avoid the fare. Fen offers a shift ferry.',[i('submit','bread',32),i('submit','white_wool',16)],[t('tamsin','the overnight workers','Nobody chose this because a stone yard is restful. Put transport in the work budget before praising their dedication.'),t('fen','the shift ferry','One trip for the first shift, one for the last, and room for tools. Reliable passage is less glamorous than rescue and usually prevents it.')],'The first workers leave at the end of their shift without calculating whether they can afford to.'),
row('The Foundation Nobody Will See','The repair is ready for public approval. Eldara asks Mara to describe the work that will disappear beneath the finished road.',[],[t('mara','the hidden foundation','Drainage, good footing, and someone willing to stop when the ground behaves differently from the drawing. Put their names beside the ribbon cutters.'),t('sera','the builders\' record','I will keep the rejected plans too. The finished road deserves an honest account of what made it safe.')],'The dedication begins with the workers who will not appear in its most attractive painting.')])

chapter('Book IV | The Roads That Remember','rr_house','XXVI | The House Made of Paper',[
row('An Invitation with Conditions','The Ledger House invites the council to negotiate, provided no river witnesses attend. Eldara sends the invitation for public reading.',[i('collect','book',6)],[t('sera','the invitation\'s conditions','They offer to settle the dispute by removing the people who can describe it. We can decline the condition without declining to listen.'),t('rowan','the negotiation seats','Reedbank chooses its own delegation. We will pay their passage and let them disagree with us in the room.')],'The reply accepts a meeting and rejects the empty seats.'),
row('A Debt Older than Its Debtor','The House claims that the river communities inherited unpaid royal maintenance charges. Sera asks who actually received the maintenance.',[i('craft','writable_book',2)],[t('sera','the inherited debt','The charge continued through years when the gates were abandoned. It is an account of an obligation, with the service quietly removed.'),t('fen','the old maintenance voyages','My predecessor ferried the repair crews only twice in that period. I will testify to the journeys I know, and leave the rest uncertain.')],'The council separates verifiable costs from fees that have survived only on paper.'),
row('The Guard at the Archive Door','Elian warns that the archive staff are being treated as accomplices because they handled the House\'s records.',[i('submit','bread',16)],[t('spire_guard','the archive staff','My order is to keep the records safe and the door open to authorized witnesses. Clerks may leave their shift. This is an archive, not a prison.'),t('elian','the staff protections','Investigate decisions, not proximity to a desk. A frightened clerk can preserve evidence; a cornered one may burn it to escape.')],'Staff are offered protection without being asked to endorse the council\'s account.'),
row('The Margin Reserved for Dissent','Reedbank\'s witnesses disagree with Rowan\'s preferred settlement. Eldara asks you to carry their objection without softening it.',[i('submit','paper',32)],[t('rowan','the dissenting petition','They think our review date is too late. Write it exactly that way. Agreement loses its meaning if we edit every refusal into a compliment.'),t('sera','the dissenting record','The objection goes beside the draft, not in a separate volume nobody reads. Future readers should see that another course was proposed.')],'The settlement remains a proposal long enough for people to change it.'),
row('A Bond with No Hostage','The House offers repair materials if the council guarantees future toll income. Mara asks who bears the risk if the repairs fail.',[i('collect','copper_ingot',24)],[t('mara','the repair bond','They receive the toll even if the wall fails. That is no guarantee of workmanship. Payment should follow inspected work, not a promise to keep collecting.'),t('jorge','the material guarantee','We can buy smaller lots from several suppliers. It takes more checking, but one angry owner cannot strand the entire repair.')],'The common works choose several modest contracts over one irresistible bargain.'),
row('The Meeting after the Meeting','The formal hearing ends without agreement. Eldara asks whether the witnesses still have a reason to return.',[],[t('fen','the witnesses\' return','Their boats are waiting, their expenses are covered, and nobody has hidden the next meeting date. That will matter more than a gracious closing speech.'),t('rowan','the next hearing','We keep negotiating. Refusing one set of terms is not the same as declaring every possible agreement impossible.')],'A second meeting is scheduled in the river district itself.')])

chapter('Book IV | The Roads That Remember','rr_hearing','XXVII | The Night of Open Doors',[
row('A Rumor before the Hearing','A rumor claims the council intends to seize every river boat. Fen asks Eldara to publish the actual draft before fear writes another one.',[i('craft','lectern',2)],[t('fen','the seizure rumor','Some captains believed it because a king once did exactly that. Do not call them foolish. Show them the clause that prevents us repeating it.'),t('rowan','the public draft','The boats remain with their crews. We can pay for passage without owning the people who provide it.')],'Copies of the proposal reach the landings before the next official speech.'),
row('The Watch at a Public Meeting','Elian expects an angry crowd. Tamsin asks where someone can leave quietly if the room becomes too much.',[i('submit','lantern',12)],[t('elian','the meeting watch','Guards stand where they can keep exits clear. Nobody is searched merely for arriving with an argument.'),t('tamsin','the quiet room','A seat outside is still a place in the meeting. We can carry questions between rooms without making anyone earn the right to be heard.')],'The meeting plan includes several ways to participate and several ways to leave.'),
row('A Translation of the Same Promise','Iona finds that the river names in the public draft are unfamiliar to half its intended readers.',[i('collect','map',4)],[t('iona','the translated map','Put the landing names beside the survey names. People should not need to abandon the words they use at home to understand a public promise.'),t('sera','the parallel text','Keep both versions together, with a place to record corrections. A translation becomes dangerous when it is treated as an invisible convenience.')],'The agreement acquires a glossary written by its readers.'),
row('The Testimony Nobody Expected','Jorge offers to describe his own sales to the gate owners. Elian worries the hearing will become a contest to identify one convenient culprit.',[i('collect','writable_book')],[t('jorge','the public testimony','I want the receipts read before my apology. An apology can sound generous while leaving the useful facts safely unnamed.'),t('elian','the witness\'s protection','He can answer questions without being handed to a crowd. Accountability needs room for an answer, even an unsatisfactory one.')],'The hearing records a responsibility that neither excuses nor explains away the whole system.'),
row('A Vote That Can Be Revisited','The delegates disagree about how often to review the river compact. Eldara asks each side to state the cost of its preferred timetable.',[i('submit','paper',16)],[t('rowan','the compact review','A short review keeps the agreement answerable but makes planning harder. A long one gives stability and more time for a bad rule to hurt people.'),t('iona','the distant delegates','If reviews are frequent, pay for distant delegates to attend. Otherwise proximity becomes an extra vote nobody wrote into the charter.')],'The council budgets for participation before selecting the review date.'),
row('The First Shared Signature','The compact is ready. Eldara asks you to recommend how its first season will be supervised.',[],[t('fen','the shared signature','The captains will sign either arrangement if river communities can stop an unsafe release. Keep that right in the part everyone signs.'),t('rowan','the first season','We will record your recommendation and the objections to it. Neither arrangement should survive merely because admitting a mistake would be embarrassing.')],'The compact is signed with a review date and a clear right to call a halt.')],choice=[dict(title='Rotating local stewards',result='Each landing names a steward for one season. The record emphasizes local scrutiny and the work required to keep handovers clear.'),dict(title='A joint river council',result='A shared council supervises the first season. The record emphasizes continuity and the cost of keeping distant communities represented.')])

chapter('Book IV | The Roads That Remember','rr_release','XXVIII | The River Given Room',[
row('Before Anyone Opens a Gate','The compact has been signed, but the first controlled release still requires preparations at every landing.',[i('submit','oak_boat',4)],[t('fen','the ready boats','Every landing has answered. Two asked for extra time, and received it. The agreement has begun doing its job before the gate has moved.'),t('tamsin','the evacuation check','The people who need assistance have chosen where to wait. We asked them before deciding what safety ought to look like.')],'Readiness is reported as a set of answered questions, not a single triumphant word.'),
row('The Engineer\'s Last Objection','Mara finds a worn fitting during the final inspection. The ceremony can wait; the water cannot be asked to ignore it.',[i('smelt','iron_ingot',16)],[t('mara','the worn fitting','Replace it now. Nobody gets a medal for keeping a schedule that was written before the fault was found.'),t('jorge','the replacement stock','The spare lot is here because we bought it before the emergency. Boring inventory has finally had its moment.')],'The ceremony is postponed, and the postponement appears in the official account.'),
row('Make Room for the River','Iona marks a floodplain that must remain free of new buildings. Rowan asks how to protect it without evicting its present users.',[i('submit','wheat_seeds',32)],[t('iona','the shared floodplain','Seasonal gardens can return after the water. Permanent walls cannot. Ask the growers what warning and support make the arrangement workable.'),t('rowan','the growers\' agreement','We pay for the lost season before the release. Nobody should have to fund a public benefit with a private disaster.')],'The floodplain agreement includes seed, compensation, and a date to return.'),
row('When the Warning Comes Back','The trial release proceeds in the chronicle. Eldara asks you to collect reports from the watch and harbor before declaring it complete.',[],[t('elian','the first release report','The watch reports no missing people. One path washed out sooner than expected. Put both facts in the same report.'),t('fen','the harbor report','The small landing was safe. The warning arrived with time to spare. Its keeper still wants a clearer signal, and I have promised a second test.')],'The report includes the improvement requested by the least powerful landing.'),
row('Return the Borrowed Ground','Emergency shelters stand on borrowed land. Eldara asks Rowan and Tamsin to agree on departures that do not leave people homeless again.',[i('submit','oak_planks',64),i('submit','bread',32)],[t('rowan','the shelter agreement','The emergency has ended for the council before it has ended for every family. We negotiate extensions openly instead of pretending the original promise never existed.'),t('tamsin','the last shelter residents','Let each household leave with a plan, not a deadline alone. Recovery is not a ceremony everyone reaches on the same morning.')],'The last shelter remains open under a new agreement, with its costs acknowledged.'),
row('A Road That Belongs to Its Travelers','Eldara gathers the maps, objections, repair reports, and landing names into a fourth book. One courier arrives before its cover is dry.',[],[t('sera','the fourth book','Leave the compact\'s review pages loose. A book can preserve what happened without pretending that no amendment will ever be needed.'),t('iona','the winter courier','The courier came from above the northern passes. Their village is absent from both our old maps and the new river ledger. They ask whether winter must be survived alone.')],'BOOK IV COMPLETE. The river has room to move. Beyond it, the first northern snow is falling.')])

chapter('Book V | The Winter of Unwritten Names','wn_snow','XXIX | A Letter above the Snowline',[
row('The Courier Who Kept Walking','The northern courier waited through the river hearing rather than interrupt it. Eldara asks what was urgent enough to bring them so far.',[i('collect','paper',16)],[t('iona','the northern letter','The address is White Cairn. I have a height mark for it and no road. Someone measured the mountain without recording the people living on it.'),t('tamsin','the courier\'s condition','They need rest before questions. I have their permission to tell you that the villages face a fuel shortage, and that the first pass is already closing.')],'Eldara opens a fifth book with the courier\'s own account, including the days they waited.'),
row('A Village beyond the Stamp','Rowan finds no agreement promising White Cairn relief. Sera asks whether the absence is an answer or the reason a new agreement is needed.',[i('craft','writable_book')],[t('rowan','the absent agreement','We have never promised these villages anything. That limits what they can demand from an old charter; it does not limit what we can offer now.'),t('sera','the northern records','Do not invent an ancient bond to make present kindness respectable. Record the first offer as the first offer.')],'The invitation asks what help is wanted without claiming a forgotten right to govern.'),
row('Enough for the Return','Fen cannot sail a mountain pass, but he recognizes a supply plan that spends everything on arrival.',[i('submit','bread',32),i('submit','white_wool',16)],[t('fen','the expedition reserve','Count the return rations separately. A party dependent on taking food from its hosts has not arrived bringing only help.'),t('elian','the northern escort','The escort has permission to turn back. No courier should have to keep walking merely because their report might disappoint us.')],'The supplies include a return journey and a written condition for abandoning the attempt.'),
row('Two Calendars for One Winter','The council calls the pass open until first snow. Iona learns that local carriers stop using it much earlier.',[i('craft','compass',2)],[t('iona','the carriers\' calendar','The locals watch the night ice in shaded cuts. Our calendar waits for a snowfall people in the valley can see. Their winter begins sooner.'),t('mara','the expedition timetable','Then the workshop deadline moves. A date is a tool for organizing work, not a law that makes conditions obey it.')],'Departure is moved forward and unfinished comforts are left behind.'),
row('The Words on the Welcome','Sera drafts an introduction that promises partnership. Ysolde wants the party to explain what refusing that partnership would mean.',[i('submit','book',8)],[t('ysolde','the northern introduction','Say they can refuse the survey and still accept blankets. Otherwise the blankets become a price paid for permission.'),t('sera','the offer without conditions','The letter now separates relief, mapping, and a possible compact. A yes to one will not be copied into the other two.')],'Three separate offers travel north in one envelope.'),
row('Above the Last Road Sign','The expedition reaches the edge of its reliable map in the chronicle. Eldara asks who will choose the next step.',[],[t('iona','the last marked road','From here we follow the local carrier\'s route. I will draw what they permit and mark what they ask us to leave unrecorded.'),t('elian','the guide\'s authority','The guide can call a halt without arguing with my rank. Everyone in the escort has heard that order from me.')],'The expedition crosses its first boundary by accepting that someone else knows the ground.')])

chapter('Book V | The Winter of Unwritten Names','wn_pass','XXX | The Pass That Changes Overnight',[
row('Snow Is Not Empty Ground','Iona asks for observations from a snowy plain before equipment is assigned for the high pass.',[i('biome','snowy_plains')],[t('iona','the snow survey','The smooth places are not always the safe ones. Mark wind, shelter, and the route back to the last known footing.'),t('tamsin','the cold-weather stops','Rest stops need shelter before people become exhausted. Waiting until someone cannot continue leaves us choosing under worse conditions.')],'The route gains planned stops instead of a single heroic distance.'),
row('A Rope Longer than a Promise','Mara prepares rescue lines and asks Elian who is allowed to order an unsafe rescue.',[i('craft','lead',4)],[t('mara','the rescue lines','Inspect the fastening and keep a spare. Courage will not mend a cut line halfway through a crossing.'),t('elian','the rescue limit','Nobody is required to become a second casualty to prove loyalty. We will plan a rescue before the emergency, including when to stop.')],'The crossing plan gives every traveler a partner and every partner a route to safety.'),
row('The Bell beneath the Drift','A shelter bell lies buried after a storm. Fen proposes visual markers for days when sound disappears in the wind.',[i('craft','lantern',8)],[t('fen','the lost shelter bell','At sea we never depend on one signal. Keep the bell, add a light, and tell travelers what either signal actually means.'),t('iona','the shelter markers','Each marker points to the next shelter and back to this one. A sign should help someone abandon a journey as well as continue it.')],'The marked route offers both directions with equal clarity.'),
row('The Pass Keeper\'s Refusal','The keeper of a narrow crossing refuses the expedition permission to continue. Eldara asks you to carry the reason without turning it into an insult.',[i('collect','writable_book')],[t('elian','the refused crossing','The ice shifted last night. We hired their judgment; now we use it. Tell the council the party is delayed by a decision that may have saved it.'),t('rowan','the delayed relief','Send support by the lower route. Do not make the keeper responsible for every consequence of refusing one unsafe passage.')],'Two smaller deliveries replace the single journey that could no longer be made safely.'),
row('Warmth at the Turnaround','Tamsin asks for a shelter where turning back does not mean going without food.',[i('submit','baked_potato',32),i('submit','coal',24)],[t('tamsin','the turnaround shelter','A retreat should lead somewhere warm. People take terrible risks when the safe choice looks like punishment.'),t('fen','the lower-route supplies','The boats can carry supplies to the foothills while the pass is closed. We have a useful job even when we cannot finish the whole route.')],'The expedition loses time without losing its way home.'),
row('The Guide Draws the Boundary','White Cairn permits the expedition to enter by the lower path but asks that a protected ridge stay off public maps.',[],[t('iona','the protected ridge','I can mark the boundary without recording what lies inside it. A useful map need not satisfy every curiosity.'),t('ysolde','the ridge agreement','Keeping a promise of privacy is part of arriving peacefully. The villages will notice whether we respect a small refusal before trusting us with a larger one.')],'The first northern map includes a blank space that is there by agreement.')])

chapter('Book V | The Winter of Unwritten Names','wn_fuel','XXXI | The Warmth in Someone Else\'s Ledger',[
row('A Warehouse with a Warm Office','The villages have timber but little seasoned fuel. Jorge recognizes a contract that charges storage fees while delaying delivery.',[i('collect','coal',32)],[t('jorge','the winter fuel contract','The supplier earns more while the fuel waits. That does not prove every delay was deliberate, but it gives us a reason to inspect the dates.'),t('sera','the delivery records','We compare signed receipts, weather reports, and the carriers\' accounts. A neat pattern in one ledger is a question, not yet a verdict.')],'The inquiry opens with records that can contradict one another.'),
row('Burning the Next Year','Mara worries that emergency cutting will consume the seedlings needed for future fuel.',[i('smelt','charcoal',24)],[t('mara','the charcoal trial','Measure the wood used as well as the heat gained. A method can solve tonight by making next winter worse.'),t('tamsin','the fuel gardens','Keep seed trees and leave the slopes that shelter the village. A bare hillside changes more than the woodpile.')],'The relief plan reserves future growth before expanding the fuel harvest.'),
row('An Account beside Every Hearth','Rowan wants household estimates. Tamsin warns that an inventory of private need can become a list people are ashamed to join.',[i('craft','writable_book',3)],[t('tamsin','the household estimates','Ask what warmth is needed, not why a household deserves it. Keep individual details with the people arranging deliveries.'),t('rowan','the public fuel account','Publish totals and shortages. The council can be answerable without publishing whose children sleep in which room.')],'The public report shows the gap without displaying the households inside it.'),
row('A Fair Price for a Difficult Road','The carriers refuse the council\'s proposed rate. Fen asks why a dangerous mountain delivery was priced like a short river crossing.',[i('collect','emerald',16)],[t('fen','the carrier rate','The old figure counted distance and ignored weather, return loads, and days waiting safely. Underpaying caution encourages someone to skip it.'),t('jorge','the revised delivery price','Pay the waiting time when the pass is closed. Then a safe delay is a cost we share, not a loss pushed onto the driver.')],'The contract pays for safe decisions that produce no impressive arrival.'),
row('The Storekeeper Who Stayed','The local storekeeper admits keeping a reserve secret, fearing a rush on supplies. Eldara wants a workable remedy as well as an honest account.',[i('submit','charcoal',32)],[t('rowan','the hidden reserve','Bring the stock into the common count, record the decision, and protect access to the store. Shame alone will not distribute a single basket fairly.'),t('elian','the storehouse watch','The watch will prevent threats and report shortages. It will not decide whose stove matters most.')],'The reserve becomes part of the relief plan under an account everyone can inspect.'),
row('Enough Heat to Disagree','The fuel committee can choose local stores or a shared reserve. Eldara asks whose failure would be easiest to repair.',[],[t('mara','the reserve arrangement','Several stores resist one broken roof. One common store is easier to inspect. Either needs people with time and tools to keep it sound.'),t('rowan','the winter reserve decision','Choose the first arrangement, then write how to change it. A winter trial should not become a permanent law by accident.')],'Fuel reaches the villages under a plan with published stocks and a spring review.')],choice=[dict(title='Several village stores',result='Local stores receive separate inspections and mutual-aid commitments. The spring review will compare shortages between villages.'),dict(title='One shared reserve',result='A shared reserve publishes daily stock figures and keeps local emergency caches. The spring review will examine access and travel costs.')])

chapter('Book V | The Winter of Unwritten Names','wn_stars','XXXII | A Light That Answers No King',[
row('The Observatory on the Old Map','Sera finds an abandoned observatory overlooking the pass. Its last keeper recorded weather long after royal payments stopped.',[i('craft','spyglass')],[t('sera','the keeper\'s notebooks','The final years have the most careful observations and the fewest signatures. Nobody paid for the work, so the palace assumed it had ended.'),t('iona','the observatory route','The ridge can be approached without entering the protected ground. I will ask the guides to check that before drawing a public path.')],'The expedition seeks permission to restore a weather station, not a royal outpost.'),
row('Glass for a Patient Window','Mara says the observation room needs reliable windows more than an impressive new tower.',[i('smelt','glass',32)],[t('mara','the observation room','Weather work requires people to stay long enough to notice a change. Start with a dry room and a chair that does not break.'),t('tamsin','the observers\' rota','No one keeps the entire night watch alone. Fatigue can look like dedication until it becomes a missed warning.')],'The restoration budget begins with ordinary comfort and overlapping shifts.'),
row('A Warning without a Command','Elian asks how weather reports become decisions. Iona wants the station to explain uncertainty without issuing travel orders.',[i('craft','redstone_lamp',4)],[t('iona','the warning signals','Use separate signals for observed danger and uncertain conditions. If every light means absolute certainty, someone will wait too long to light it.'),t('elian','the station\'s authority','The station reports what it sees. The route keepers decide passage using that report and the ground beneath their feet.')],'The warning code separates observation, uncertainty, and local judgment.'),
row('Three Nights in the Margin','The old notebook contains three contradictory wind reports. Sera asks you to keep them together while Mara checks the instrument.',[i('craft','clock')],[t('mara','the old wind instrument','The vane catches when ice builds on the bearing. One observer freed it; another recorded it as found. Both wrote honestly about different conditions.'),t('sera','the contradictory reports','We add the instrument fault beside the entries. Correcting the explanation does not require erasing the evidence that led us to it.')],'The recovered record includes the circumstances of its own mistakes.'),
row('A Beacon for Those below','Fen proposes testing the warning from the landing that most needs to see it.',[i('submit','glowstone',8)],[t('fen','the distant signal test','From the tower it is brilliant. From the lower landing it disappears behind a roof. A signal works where it is received, not where it is admired.'),t('iona','the relay position','Place a relay with the landing keeper\'s agreement and test it in poor weather. A clear day proves only what happens on a clear day.')],'The warning network gains a modest relay after an unsuccessful public test.'),
row('The First Forecast Nobody Owns','The station is ready. Eldara asks Sera and Rowan to settle who may read its observations.',[],[t('sera','the open forecasts','Copies go to carriers, villages, and anyone maintaining a route. Nobody should need permission from a patron to learn that a storm is coming.'),t('rowan','the station charter','The council pays its share without owning the forecasts. Local observers keep authority over their work and publish corrections beside predictions.')],'The restored light answers the weather and the people who travel beneath it.')])

chapter('Book V | The Winter of Unwritten Names','wn_shelter','XXXIII | Guests with Claws',[
row('Tracks beside the Woodpile','Ysolde reports that a displaced dragon has been following fuel caravans. Elian wants the observation distinguished from an attack report.',[i('collect','cooked_beef',24)],[t('ysolde','the caravan tracks','The tracks stop where spilled food was left. That may explain the visits; it does not make approaching the animal safe. Change the storage before organizing a hunt.'),t('elian','the caravan watch','The watch keeps people back and records behavior. We will respond to an actual threat without pretending every footprint is one.')],'The caravans secure their food and keep a cautious distance.'),
row('A Refuge Cannot Be a Trap','Tamsin and Ysolde consider a temporary refuge away from homes. Iona checks that it does not block a customary village route.',[i('submit','oak_fence',48)],[t('iona','the proposed refuge','The apparently empty gap is the winter footpath. Move the boundary or people will have to choose between trespass and a dangerous detour.'),t('ysolde','the refuge exits','Leave a route for the animal to depart and a separate route for keepers to retreat. A refuge with no exits becomes a confrontation waiting for a bad day.')],'The proposal reserves safe passage for residents, keepers, and the displaced creature.'),
row('The Cost of Keeping Distance','Jorge asks who pays for ruined provisions. Rowan refuses a policy that demands patience from people while leaving them with the loss.',[i('submit','emerald',12)],[t('jorge','the damaged provisions','Compensation needs a clear claim and a date for payment. A sympathetic speech does not replace a winter food stock.'),t('rowan','the refuge compensation','The common fund covers verified losses and prevention supplies. People can support restraint more readily when they are not asked to subsidize it alone.')],'A small compensation fund accompanies the refuge rules.'),
row('Listen before Naming It Hunger','Tamsin wants the keepers to record several explanations for the visits rather than making one guess into a fact.',[i('craft','writable_book',2)],[t('tamsin','the observation log','Record the weather, noise, food, and the animal\'s route. We may discover a pattern, or learn that our first theory was too simple.'),t('ysolde','the keepers\' observations','Let an unanswered question stay unanswered. Calling uncertainty expertise makes the next mistake harder to admit.')],'The log leaves room for observations that challenge its opening theory.'),
row('No Trophy for a Quiet Week','Caelen says a week without an attack should count as success even if the watch cannot display proof on a wall.',[i('craft','shield',2)],[t('caelen','the quiet refuge watch','The best outcome gives us no trophy. I will sign a contract for safe journeys and careful reports, not for producing a carcass to prove we worked.'),t('elian','the watch report','We record the protected trips and the times we withdrew. A retreat that avoids an injury belongs in a successful report.')],'The refuge watch publishes a week of safe passage and several prudent withdrawals.'),
row('The Path Left Open','The dragon moves on in the chronicle. Eldara asks what should remain after the temporary refuge closes.',[],[t('ysolde','the empty refuge','Keep the observations and the safe-distance rules. Remove the temporary barriers before someone mistakes them for a claim on the valley.'),t('iona','the reopened footpath','The path goes back on the public map after the residents check it. Restoration is a task, not something we assume happens when we stop using a place.')],'The refuge ends with the return of a path and an account of what it cost.')])

chapter('Book V | The Winter of Unwritten Names','wn_names','XXXIV | The Names below the Totals',[
row('A Register with Too Few Lines','The relief register counts buildings. Tamsin knows several households share the same roof.',[i('submit','paper',32)],[t('tamsin','the crowded register','One roof is not one household. Ask the residents how supplies are shared instead of dividing a total by the number of doors.'),t('rowan','the revised relief count','We correct the allocation and publish the reason. A mistaken count can be repaired without making the people it missed prove they were inconveniently real.')],'The next delivery includes households the first calculation concealed.'),
row('The Name Someone Does Not Use','Sera finds that the old royal register records a villager under a name they have left behind.',[i('collect','book',4)],[t('sera','the corrected name','Their current name belongs in the working register. The old document can remain in the archive with access limited where it could cause harm.'),t('rowan','the register correction','No public hearing is needed to make a clerk use the right name. We can audit the change without turning a person\'s history into an exhibit.')],'The working register is corrected without demanding a public explanation.'),
row('Letters Held through Winter','Fen has a bundle of letters delayed by the closed pass. Elian wants families warned that a late message may describe an earlier danger.',[i('craft','chest',2)],[t('fen','the delayed letters','I will preserve the dates and say when each bundle traveled. Silence in winter can mean a blocked road, not an abandoned promise.'),t('elian','the families\' notice','Give families what we know and what we cannot yet know. Do not fill a frightening silence with reassurance we have no evidence for.')],'The letters arrive with a delivery history and an honest account of the remaining gaps.'),
row('A Witness Can Change Their Mind','A village speaker withdraws permission to include their story in the public chronicle. Eldara asks Sera to honor the request before printing.',[i('collect','ink_sac',8)],[t('sera','the withdrawn testimony','The public copy will omit it. We can explain that a contribution was withdrawn without hinting at what it said.'),t('iona','the survey consent','The same rule belongs in the map notes. Agreement given during an emergency should have a way to be reconsidered afterward.')],'The chronicle gains a statement of its limits instead of a story taken against its teller\'s wishes.'),
row('Those Who Remain Missing','The winter list still contains unanswered names. Tamsin asks for a place where families can leave new information without repeating their loss at every desk.',[i('craft','lectern',2),i('craft','lantern',4)],[t('tamsin','the missing-person desk','Give each family one contact and a way to update the record. We cannot promise an answer; we can stop making them begin again each time they ask.'),t('elian','the search handover','The watch will pass on leads with dates and sources. An unverified sighting remains a lead, not an announcement of a return.')],'The search continues under a record designed to survive changes of staff.'),
row('A Chronicle with Blank Pages','Eldara asks how to close a chapter while its missing names remain unresolved.',[],[t('sera','the unfinished register','Close the account of this winter, not the search. Leave a dated page for later answers and say who will keep it.'),t('tamsin','the next keeper','The families know where to bring news. That is a smaller promise than certainty, and one we can actually keep.')],'The fifth book keeps blank pages whose purpose is explicitly named.')])

chapter('Book V | The Winter of Unwritten Names','wn_council','XXXV | Seats for the People beyond the Map',[
row('An Invitation That Pays the Fare','The northern villages are invited to a spring council. Fen asks whether the invitation includes the cost of arriving.',[i('submit','emerald',16)],[t('fen','the delegates\' passage','A seat is not accessible if reaching it costs a household its seed money. Put fares and lodging beside the invitation.'),t('rowan','the council budget','The travel fund is open to every delegation by the same published rule. Attendance should not depend on a private favor from a steward.')],'The council funds participation before deciding how many chairs to set out.'),
row('A Delegate Is Not a Village','Iona asks how distant residents can challenge a delegate who claims unanimous support.',[i('craft','writable_book',4)],[t('iona','the delegates\' mandate','Record what each delegate has permission to agree to, and what they must take home for discussion. Distance should not turn consultation into a blank signature.'),t('sera','the dissenting letters','Letters of disagreement travel with the mandate. A village can send one delegate and still have more than one opinion.')],'The council packet includes limits, objections, and a route for asking again.'),
row('The Watch outside the Council','Elian wants guards available for safety without making military presence part of the negotiation.',[i('submit','bread',24)],[t('elian','the council watch','The guards stay at the entrances and respond to specific threats. A delegate should not have to agree beneath a row of drawn weapons.'),t('spire_guard','the delegates\' access','I have the access list and instructions to help people find the meeting. Disagreement with the council is not a reason to refuse entry.')],'The watch briefing describes service at a meeting rather than control over it.'),
row('The Offer a Village May Refuse','One northern village wants weather reports and no shared government. Rowan asks whether cooperation can survive that answer.',[i('submit','book',8)],[t('rowan','the limited agreement','Yes. Share the reports, keep the relief account, and leave membership for them to reconsider. Help already given is not a debt payable in sovereignty.'),t('ysolde','the refused membership','Then make the limited agreement visible. Other villages should know that refusing a wider compact does not make them enemies.')],'The council writes a place for cooperation outside membership.'),
row('The Amendment Written after Supper','A late proposal would move disputes to a court too far away for most villagers to use. Jorge asks who can afford to be right there.',[i('collect','paper',24)],[t('jorge','the distant court clause','A good rule with an unreachable hearing can protect only the people who travel easily. Start with a local hearing and publish a route for appeal.'),t('sera','the late amendment','Circulate the new clause before voting. Exhaustion and surprise are poor substitutes for agreement.')],'The vote is delayed until the amendment can be read outside the meeting room.'),
row('A Covenant with Open Edges','Eldara asks you to recommend the first structure for northern cooperation. Both drafts protect the right to refuse broader membership.',[],[t('rowan','the northern covenant','A federation shares decisions and the work of attending them. A network of agreements is easier to join narrowly and harder to coordinate. Neither removes the need to listen.'),t('iona','the boundaries of the compact','Whichever form is chosen, draw its edges in pencil. A map of cooperation should show where people agreed, not where we hope to own them.')],'The northern covenant is adopted for a trial year with local ratification and a published review.')],choice=[dict(title='A federation by local ratification',result='Villages may ratify a shared council with limited powers. Each receives the text, travel support, and a clear withdrawal procedure.'),dict(title='A network of specific agreements',result='Villages sign the services they want to share. Coordinators publish the gaps between agreements so no community is silently assumed to be covered.')])

chapter('Book V | The Winter of Unwritten Names','wn_spring','XXXVI | The Work after the Last Page',[
row('The Thaw Finds Every Weak Join','The spring thaw reveals leaks in the temporary shelters. Mara asks for repairs before the closing ceremony.',[i('submit','spruce_planks',64),i('smelt','iron_ingot',16)],[t('mara','the thaw repairs','Winter proved the shelters could keep people alive. Spring is asking whether they can remain dry. Passing one test does not mean the work has stopped changing.'),t('tamsin','the shelter departures','Families leave when their next home is ready. The calendar has thawed faster than some roofs.')],'The ceremony budget loses a decoration and gains several sound repairs.'),
row('Return What Was Borrowed','Fen inventories borrowed boats, tools, and bedding. Jorge wants the damaged items named before anyone signs a return receipt.',[i('craft','chest',4)],[t('fen','the borrowed equipment','Check every return with its owner. A tired volunteer should not discover later that helping us cost them their only useful boat.'),t('jorge','the replacement account','Repairs and replacements belong in the winter cost. Omitting them makes the next relief plan look cheaper by hiding who paid.')],'The public account includes the less photogenic work of putting borrowed things right.'),
row('Seeds beyond the Pass','Tamsin asks northern growers which seed they actually want. Iona adds the permitted deliveries to a map that now carries local names.',[i('submit','wheat_seeds',64),i('submit','potato',32)],[t('tamsin','the spring seed request','We send what the growers requested and keep their planting advice with the stock. A familiar crop here may fail on their hillside.'),t('iona','the spring delivery map','The names have been checked by the villages. The protected ridge remains blank. Knowing more has not made every boundary disappear.')],'The first spring delivery follows a map made with its recipients.'),
row('The Report That Includes Us','Eldara asks every institution involved to record one mistake and its remedy before celebrating the season.',[i('craft','writable_book',4)],[t('elian','the watch\'s own report','We underestimated waiting time and overpacked the first escort. The remedy is in next winter\'s schedule, with someone assigned to check it.'),t('sera','the institutional corrections','An admission becomes useful when a later reader can find what changed. I have linked each correction to a person responsible for following it up.')],'The chronicle records corrections that can be checked after its authors have left the room.'),
row('A Place at an Ordinary Table','The companions gather for a meal without a council agenda. Eldara sends you to invite those most likely to keep working through it.',[i('submit','bread',32),i('submit','cooked_cod',24)],[t('mara','the ordinary supper','The tools are put away. Tell Tamsin I mean it this time. If the world needs a hinge during supper, it can wait until the plates are cleared.'),t('tamsin','the invitation to rest','I will come if someone else takes the late check. Rest is easier to accept when it has been arranged rather than merely recommended.'),t('fen','the late check','I have the late check. Save me a plate and let the others eat while the bread is warm.')],'The table fills gradually, with a place saved for the person still on duty.'),
row('The Next Page Belongs to Someone Else','Eldara prepares to close the fifth book. She asks you to hear the archivist, the traveler, and the steward before deciding what a finished chronicle means.',[],[t('sera','the fifth book','We have recorded what we know, the accounts that disagree, and the questions still open. That is enough to close a volume without claiming the world is settled.'),t('iona','the next journey','There are roads I have not walked. I no longer mark them empty. When I go, I will bring questions and enough supplies to return.'),t('rowan','the work that continues','The kitchens, hearings, ferries, and repairs will continue tomorrow. A covenant is kept in those ordinary appointments. Thank you for helping us make promises people can find.')],'BOOK V COMPLETE. Eldara leaves a fresh notebook beside the five finished volumes. The next story may begin in another hand.')])

SIDE=[]
def side(owner,title,entries):
    assert len(entries)==(6 if owner in ('caelen','jorge') else 8)
    SIDE.append((owner,title,entries))
def s(title,story,work,npc,subject,response,after):
    return row(title,story,work,[t(npc,subject,response)],after)

side('rowan','A Key for Every Neighbor',[
s('The Lock on the Common Room','Rowan inherited a public room whose key is held by someone who has moved away. Ask Mara to inspect its lock.',[i('collect','iron_ingot',4)],'mara','the common-room lock','The lock is sound. Its ownership is the problem. I can repair the fittings, but Rowan needs a key policy before someone else becomes the only person who can open the door.','Rowan posts opening hours and names two keyholders.'),
s('A Room after the Ferry','The room closes before the last ferry arrives. Rowan asks whose journeys its timetable overlooks.',[i('craft','lantern',4)],'fen','the evening visitors','The late boat carries workers. Keep one evening open and I will put the hours beside the landing schedule.','An evening session opens for residents arriving after work.'),
s('Chairs with a Reason to Stay','Rowan asks Tamsin what makes a meeting room usable for more than its quickest speakers.',[i('submit','oak_planks',24),i('submit','white_wool',8)],'tamsin','the meeting-room seats','Seats near the exit, room to move, and breaks announced in advance. People should not have to disclose a private difficulty to ask for a comfortable place.','The room gains quiet seats and scheduled breaks.'),
s('The Rules on One Page','Rowan asks Sera to shorten the room\'s inherited regulations.',[i('submit','paper',16)],'sera','the common-room rules','Keep the purpose, hours, and way to complain. A rule that needs a clerk to translate it gives the clerk more power than the rule admits.','The notice fits on one page, with a contact for corrections.'),
s('The First Unwelcome Question','A visitor challenges Rowan at an open session. Elian has been asked to attend the next meeting.',[i('submit','bread',8)],'elian','the difficult meeting','I will keep the exits safe. I will not remove someone for asking Rowan an uncomfortable question. Tell him the watch expects him to answer it himself.','Rowan answers the question in the public minutes.'),
s('A Fund Nobody Has to Beg For','The room needs a repair fund. Rowan asks Jorge for an account that protects donors\' privacy.',[i('collect','emerald',8)],'jorge','the common-room account','Publish income, spending, and receipts. Gifts can be anonymous without making the spending anonymous too.','A public ledger records each repair and its receipt.'),
s('An Address Everyone Can Find','Iona notices the room appears under three different names. Rowan asks for a usable direction.',[i('craft','map')],'iona','the common-room address','Use the name on its door and describe the nearest crossing. Keep the older names in the index so a newcomer carrying an old note can still find it.','The room appears on the map with its opening hours.'),
s('The Spare Key','Rowan wants to leave the room in other hands for an afternoon. Ask Mara whether the repairs can wait.',[i('craft','tripwire_hook',2)],'mara','the spare key','The repairs are finished. The door works without Rowan standing beside it. A useful public room should survive its steward taking a walk.','Rowan gives a second steward the key and leaves before the meeting ends.')])

side('sera','The Margins Answer Back',[
s('A Book Returned with Notes','Sera receives a library book full of objections. Ask Rowan whether the library has ever invited corrections.',[i('collect','book',4)],'rowan','the annotated library book','Our rules mention damage six times and questions not once. Copy the objections and ask the reader whether we may circulate them.','Sera starts a folder of reader corrections.'),
s('Ink for an Uncertain Memory','A sailor remembers a voyage differently from the official account. Sera sends you to Fen for the working record.',[i('collect','ink_sac',4)],'fen','the disputed voyage','The log records the route we intended. The repair account records where we actually stopped. Keep both before deciding the sailor remembered badly.','The library displays the log beside the repair receipts.'),
s('The Apprentice\'s Drawing','An apprentice illustrates a difficult machine. Sera asks Mara to check it without rewriting the author\'s voice.',[i('submit','paper',24)],'mara','the apprentice\'s drawing','It shows the awkward step my instructions skipped. Correct the measurements and keep the explanation. It is clearer because the apprentice remembers what was difficult.','The apprentice is credited as the author of the guide.'),
s('A Shelf beyond the Stair','Sera wants more readers to reach the reference books. Ask Tamsin what makes the reading room difficult.',[i('craft','bookshelf',2)],'tamsin','the reference shelf','Bring the most-used books down and provide copies that can leave the room. Access is more than being allowed through the front door.','A lending reference shelf opens beside the entrance.'),
s('The Map with a Private Corner','Sera prepares a map exhibit. Iona promised not to publish one household\'s location.',[i('craft','map',2)],'iona','the exhibition map','Use the public copy. The blank corner records a promise made to the people who guided us; it is not an error to fill in.','The exhibit explains why some information is absent.'),
s('A Correction in Large Letters','A leaflet names the wrong watch volunteer. Sera asks Elian to carry the corrected account.',[i('submit','paper',16)],'elian','the mistaken credit','Print the correction where people saw the original. A quiet amendment cannot undo a public mistake if nobody knows to look for it.','The corrected leaflet thanks the right volunteer and identifies the error.'),
s('The Reader Who Disagrees Again','The annotated book returns with another objection. Sera asks Jorge how he handles a disputed receipt.',[i('collect','writable_book')],'jorge','the second objection','Show the calculation again. Explain an incorrect objection and act on a correct one. Being tired of a question does not settle it.','Sera reopens one note and explains why another remains unchanged.'),
s('A Catalogue of Questions','Sera invites Rowan to inspect a catalogue organized by questions instead of royal patrons.',[i('craft','lectern')],'rowan','the new library catalogue','I found crop records before the portrait of the king who funded their binding. That is a useful order for a library trying to feed people.','The catalogue has space for questions no current book answers.')])

side('mara','Tools That Come Home',[
s('The Hammer with Three Owners','Mara finds a hammer listed as gift, loan, and workshop stock. Ask Jorge to trace its receipts.',[i('collect','iron_ingot',8)],'jorge','the disputed hammer','The sale was canceled after the gift note was copied. I will correct the record and reimburse the lender for the time it was missing.','Mara returns the hammer with a repaired handle and an explanation.'),
s('A Loan without a Favor','Mara proposes a tool library. Rowan must decide whether borrowers need a personal recommendation.',[i('craft','chest',2)],'rowan','the tool-loan rules','A recommendation favors people who already know us. Use a simple record and repair process; let newcomers borrow under the same rules.','The tool library opens without requiring introductions.'),
s('Instructions for a Wet Afternoon','Fen reports that tool labels dissolve aboard boats. Mara asks him to test a practical lending record.',[i('craft','barrel',2)],'fen','the harbor tool crate','Put the list inside the dry lid and mark the tools themselves. A record that survives only on a workshop wall will not survive its first voyage.','The harbor receives a dry tool chest and a spare inventory.'),
s('The Handle That Hurts','An apprentice avoids one tool. Tamsin helps Mara investigate without blaming their strength.',[i('submit','leather',8)],'tamsin','the apprentice\'s handle','Ask where it hurts and change the grip. A tool made for one pair of hands is not a fair test of every other pair.','Mara adds several handle sizes to the rack.'),
s('When a Borrowed Tool Breaks','A borrower hides a cracked chisel, fearing debt. Elian suggests a less intimidating return process.',[i('craft','iron_pickaxe')],'elian','the broken-tool return','Record what happened before assigning responsibility. If every accident becomes an accusation, the next broken tool stays hidden until it injures someone.','The return rules distinguish damage, wear, and deliberate misuse.'),
s('The Cost of Teaching Slowly','Mara wants paid time to train apprentices. Rowan asks how to record work that produces fewer goods.',[i('collect','emerald',10)],'rowan','the training hours','List instruction as work. A workshop cannot teach another generation while pretending every hour must produce a saleable hinge.','The accounts include paid teaching hours.'),
s('The Apprentice Signs the Plan','Sera prepares a workshop history. Mara asks her to credit the apprentice who redesigned tool returns.',[i('craft','writable_book')],'sera','the apprentice\'s credit','Their name goes beside the design, including corrections made after the trial. Attribution should explain the work, not decorate its cover.','The apprentice signs the next revision before Mara does.'),
s('A Workshop after Closing','Mara promises to stop on time. Fen can deliver the last repaired tools.',[i('submit','iron_ingot',16)],'fen','the last tool delivery','I have the crate and receipt. Tomorrow morning is acceptable. Nothing in this box requires Mara to miss supper.','Mara closes with unfinished work safely scheduled for tomorrow.')])

side('elian','The Watch between Alarms',[
s('The Roster with No Blank Space','Elian\'s roster leaves nobody free to be sick. Tamsin requests a reserve shift.',[i('submit','bread',16)],'tamsin','the reserve watch','People become ill whether a roster permits it or not. Cover is part of staffing, not a favor granted after someone collapses.','Elian adds cover and rest periods.'),
s('The Route behind the Kitchens','Iona notices the patrol avoids a dark kitchen lane. Elian asks who uses it.',[i('craft','lantern',6)],'iona','the kitchen-lane patrol','Workers go home there after the main road quiets. Start with their arrival times instead of drawing a patrol that only looks balanced on paper.','Patrols follow the people they protect.'),
s('A Shield Is Also Weight','Mara questions identical equipment for different assignments.',[i('craft','shield',2)],'mara','the patrol equipment','The harbor watch climbs wet ladders; the gate watch mostly stands. Issue loads they can use safely and store replacements where the work happens.','Elian approves equipment by assignment.'),
s('The Complaint at the Gate','A traveler reports a guard demanding a fee. Elian sends you for the written access rules.',[i('collect','paper',8)],'spire_guard','the gate-fee complaint','There is no personal entry fee in my orders. Record the traveler\'s account. We can investigate without making them face the guard alone.','The watch publishes access rules and opens a complaint record.'),
s('The Quietest Shift Report','Caelen helps Elian recognize useful patrols without battles.',[i('kill','zombie',12)],'caelen','the uneventful patrol','List routes checked, people helped, and hazards left for the next shift. If only a fight earns recognition, someone will look for one.','Routine patrols receive credit for prevention.'),
s('A Letter without an Order','Elian writes to a former recruit. Sera offers to read the draft.',[i('craft','writable_book')],'sera','the former recruit\'s letter','Say they owe you no reply. Ask about their life before mentioning the vacancy. They should believe your concern even if they never wear the uniform again.','Elian sends no recruitment notice with the letter.'),
s('Who Checks the Captain','Rowan proposes a review of Elian\'s decisions.',[i('submit','book',6)],'rowan','the captain\'s review','The same rules apply to you. People may give evidence without your permission; you may answer without controlling the record.','Elian signs the terms before reading the complaints.'),
s('The Alarm Someone Else Answers','Elian takes a day away. Fen agrees to manage routine messages until the duty officer arrives.',[i('craft','clock')],'fen','the captain\'s day away','The officer has the roster. I will call Elian only for the defined emergencies, not because his name is easier to find than the handover.','The watch completes a day under another leader.')])

side('iona','An Atlas with Return Routes',[
s('The Path Drawn through a Garden','A proposed shortcut crosses a garden. Iona asks Tamsin where visitors can pass.',[i('craft','map')],'tamsin','the garden shortcut','The outside path stays open. The beds are somebody\'s work, not blank ground between convenient points. Ask before adding an entrance.','The atlas clearly marks the public path.'),
s('A Map for the Last Boat','Fen asks Iona to include the late landing.',[i('collect','paper',12)],'fen','the last-boat map','Mark when service ends and where someone can wait safely. A landing without a timetable is half a direction.','The map gains hours and a waiting shelter.'),
s('The Bridge That Cannot Be Promised','Mara inspects an unreliable bridge. Iona asks how to mark its changing condition.',[i('craft','compass')],'mara','the uncertain bridge','Mark the inspection date and alternative crossing. Do not print safe in permanent ink over a structure we are still repairing.','The atlas gains dated condition notes.'),
s('A Name Borrowed from a Home','Sera finds a village labeled for a former landlord. Iona asks for its present name.',[i('craft','writable_book')],'sera','the village-name index','Lead with the residents\' name and keep the old one in the index. Readers can find the place without making the landlord its owner on every page.','The present name appears on the map.'),
s('The Road a Patrol Does Not Own','Elian offers survey escorts. Iona wants refusal to remain possible.',[i('submit','bread',16)],'elian','the optional survey escort','The escort is an offer. We explain dangers and respect a refusal. Public travel cannot depend on agreeing to be watched by us.','Notices separate route information from escort arrangements.'),
s('The Scale of a Tired Journey','Tamsin asks Iona to mark rest stops.',[i('craft','lantern',4)],'tamsin','the resting-place map','Show shelter, water, and seats. Two journeys of equal length can ask very different things of the traveler.','The atlas adds a page of comfortable stops.'),
s('Corrections at the Counter','Jorge offers a map-correction box. Iona asks him to retain uncertainty.',[i('craft','chest')],'jorge','the correction box','I will date each report and protect sources when asked. You verify them; the loudest customer does not automatically become our cartographer.','Unverified corrections enter an inspection queue.'),
s('The Copy She Keeps','Iona sends Rowan the public atlas and keeps her traveling copy.',[i('submit','book',8)],'rowan','the public atlas','The public copy leaves room for changes. Keep your old one. Serving everyone need not mean surrendering every personal note.','Iona packs a blank page and supplies for the return.')])

side('tamsin','The Garden Keeps Its Keeper',[
s('A Garden without a Rest Day','Tamsin asks Mara to fix tools that make the garden take every hour.',[i('collect','iron_ingot',8)],'mara','the garden tools','The handles split and blades are blunt. Repairs save effort, but you also need a second keeper. Better tools cannot replace a day off.','Tamsin advertises for a paid assistant.'),
s('What the Soil Remembers','Iona helps Tamsin investigate a failing bed.',[i('collect','wheat_seeds',24)],'iona','the failing garden bed','Record light, water, and previous planting. Leave the cause open until observations support it; a notebook may begin with an unanswered question.','The log tracks conditions alongside harvests.'),
s('The Pantry beyond the Harvest','Fen offers storage for surplus. Tamsin asks for a rotation plan.',[i('craft','barrel',3)],'fen','the garden pantry','Date each batch and put oldest usable stock nearest the door. A full pantry conceals waste when nobody knows what arrived first.','The pantry receives labels and an inspection rota.'),
s('A Request without an Explanation','Rowan asks visitors to justify each request. Tamsin proposes a shorter form.',[i('submit','paper',16)],'rowan','the garden aid form','We need the request and delivery details, not an account of someone\'s worst month. I will remove questions we cannot justify using.','The shorter form protects private circumstances.'),
s('The Recipe in the Margin','Sera finds conflicting garden recipes. Tamsin requests careful labeling.',[i('craft','writable_book',2)],'sera','the conflicting garden recipes','Both remain historical notes marked unverified. An interesting account must be distinguishable from an approved instruction.','The archive separates testimony from garden practice.'),
s('A Watch for the Quiet Hours','Elian arranges night checks so Tamsin can leave.',[i('craft','lantern',6)],'elian','the garden night check','The list explains what to inspect and whom to call. We contact Tamsin for a real problem, not because nobody read the instructions.','A clear handover replaces constant calls.'),
s('The Apprentice Has a Question','Mara\'s apprentice designs a raised bed. Tamsin asks its user to choose the height.',[i('submit','oak_planks',32)],'mara','the raised-bed plan','We test a small section with the gardener. A desk measurement should not decide how someone bends for years.','The bed is built after a practical trial.'),
s('One Evening outside the Gate','Tamsin asks Fen to confirm the handover before taking an evening away.',[i('submit','bread',16)],'fen','the garden evening handover','The stock is counted, delivery covered, and assistant has the key. Go while there is light enough to enjoy the walk.','Tamsin leaves the garden in capable hands.')])

side('fen','The Harbor on an Ordinary Day',[
s('A Berth for an Unfamiliar Boat','Fen asks Rowan to stop reserving safe berths for familiar captains.',[i('submit','oak_planks',24)],'rowan','the newcomer\'s berth','Allocate by need, size, and weather. Familiar captains join the same queue. Rules should explain the harbor rather than preserve our friendships.','The berth board publishes practical rules.'),
s('The Ladder below the Waterline','Mara inspects a rescue ladder unreachable at low water.',[i('craft','ladder',12)],'mara','the rescue ladder','Extend it below ordinary low water and test it wet. Appearing in an inventory does not make a ladder a working rescue device.','The repaired ladder is tested from the water.'),
s('The Harbor Map at Night','Iona helps Fen distinguish similar lights.',[i('craft','lantern',8)],'iona','the night-harbor marks','Give each landing a distinct pattern and mark it on the chart. People should not need daylight to identify the light they followed.','The chart shows each landing\'s pattern.'),
s('Supplies for the Passenger Who Waits','Tamsin requests food and blankets for canceled sailings.',[i('submit','bread',24),i('submit','white_wool',12)],'tamsin','the canceled-ferry supplies','Warm the waiting place before announcing the update. Uncertainty should not also mean hunger and cold.','The cancellation plan includes meals and updates.'),
s('The Receipt That Came Back Wet','Jorge helps Fen reconstruct a ruined receipt.',[i('collect','paper',12)],'jorge','the damaged receipt','Compare copies and stock counts. Wet paper does not prove a customer owes a second payment.','The harbor stores duplicate receipts on shore.'),
s('A Rescue without an Audience','Elian offers volunteers for drills. Fen wants room to make and correct mistakes.',[i('craft','oak_boat',2)],'elian','the rescue exercise','Record what failed and repeat after corrections. Volunteers should leave prepared, not merely glad someone else made the largest mistake.','The second drill is quieter and safer.'),
s('Names beside the Cargo Totals','Sera asks Fen for deckhands\' stories.',[i('craft','writable_book',2)],'sera','the deckhands\' record','Invite accounts and allow refusals. Their work belongs in the record; their private lives do not automatically belong to the archive.','Crews contribute accounts by choice.'),
s('The Ferry That Leaves without Him','Fen lets another captain take the route. Iona checks the chart.',[i('craft','compass')],'iona','the independent ferry chart','The stops and return bearings are here. If the captain finds a gap, we amend the chart instead of deciding that only Fen can sail it.','Fen watches the ferry depart over an unhurried breakfast.')])

side('ysolde','A Sanctuary with an Exit',[
s('The Fence around an Idea','Ysolde proposes a temporary shelter. Iona checks the ground before construction.',[i('collect','oak_fence',32)],'iona','the sanctuary boundary','A path crosses the western edge. Move the shelter inward. Protection for one life should not cut another person off from home.','The sanctuary begins with a revised boundary.'),
s('Food Is Not a Summons','Tamsin asks Ysolde to secure provisions away from visitors.',[i('submit','cooked_beef',16)],'tamsin','the sanctuary food stores','Store food away from the approach and log its use. Unplanned feeding can teach an animal to seek people whose reactions it cannot predict.','Food storage is separated from the public route.'),
s('The Hunter Reads the Tracks','Caelen agrees to inspect without assuming every track requires a hunt.',[i('craft','spyglass')],'caelen','the sanctuary tracks','These marks show passage, not an attack. Make room and watch. If a threat appears, describe its behavior before choosing a response.','The log distinguishes presence from danger.'),
s('A Gate Opened from Both Sides','Mara designs a retreat route for keepers.',[i('craft','oak_fence_gate',4)],'mara','the keeper\'s retreat','The latch must work from safety under stress. Test with cold hands and an obstructed path, not only in a tidy workshop.','The gate passes a practical rehearsal.'),
s('The Visitor Who Wanted Proof','Elian helps answer visitors seeking a closer look at a resting dragon.',[i('craft','lectern')],'elian','the sanctuary visitor rule','The boundary remains. Curiosity is understandable; permission is still required. We can explain that without turning refusal into a quarrel.','Visitors receive a clear rule and its reason.'),
s('A Ledger without a Menagerie','Sera asks how to record creatures without claiming ownership.',[i('craft','writable_book',2)],'sera','the sanctuary catalogue','Record dates, observations, and uncertainty. Leave space for departure. Following a living creature in a book does not make it ours.','Departures become ordinary entries.'),
s('The Cost of an Empty Enclosure','Rowan questions the budget for a sometimes empty shelter.',[i('collect','emerald',8)],'rowan','the empty sanctuary budget','Prepared space has value before an emergency fills it. We can inspect costs without asking you to keep an animal captive to justify them.','The budget funds readiness.'),
s('After the Last Guest Leaves','Fen offers to move temporary barriers. Ysolde wants the borrowed ground restored.',[i('submit','oak_planks',24)],'fen','the sanctuary return cargo','I will store the reusable sections. Inspect the ground with its users afterward; an empty enclosure can still leave a damaged path.','The shelter closes a season by restoring the ground.')])

side('caelen','Hunts without Trophies',[
s('The Contract Names a Road','Caelen asks Elian to define a threatened route before agreeing to a vague hunt.',[i('kill','zombie',16)],'elian','the road-hunt contract','The eastern approach is threatened after dark. Clear it, date the report, and brief the next watch. A kill count alone cannot tell travelers the road is safe.','Caelen specifies the route and reporting duty.'),
s('Tracks across the Same Ground','Iona helps distinguish a creature\'s route from separate sightings.',[i('craft','compass')],'iona','the repeated sightings','Several sightings may be one moving animal. Mark dates and direction before estimating a population from frightened reports.','The board groups related observations.'),
s('A Hunt Stopped at the Boundary','Ysolde requests a nesting area remain outside the contract.',[i('craft','spyglass')],'ysolde','the nesting-ground boundary','Observe from the edge and leave the approach open. The reported threat was elsewhere. An uneventful search does not need a substitute target.','Caelen marks an exclusion around the nests.'),
s('Armor after the Assignment','Mara requests equipment checks between commissions.',[i('smelt','iron_ingot',12)],'mara','the hunters\' repairs','Check straps and joints as well as dents. Something can look intact and fail at the first important movement. Repair it before departure.','Caelen adds a check between contracts.'),
s('The Person Who Waited at Home','Tamsin asks for honest news about a delayed hunter.',[i('submit','bread',16)],'tamsin','the delayed hunter','Give the last confirmed location, who is checking it, and the next update time. Promise a report, not an outcome beyond your control.','The office records contacts and update arrangements.'),
s('Paid for Coming Back Safely','Jorge helps Caelen pay for useful work when a threat moves on.',[i('collect','emerald',12)],'jorge','the revised hunt payment','Pay for the agreed survey and evidence. Requiring a corpse regardless of conditions buys pressure to find a victim.','Caelen posts a contract for careful work and a useful report.')])

side('jorge','The Price of a Promise',[
s('The Receipt under the Counter','Jorge finds an unpaid refund. Ask Sera to record its correction.',[i('collect','paper',12)],'sera','the old refund','Keep the original and dated correction. An account should show how it was repaired so the mistake is easier to recognize next time.','Jorge sets the refund aside with a clear record.'),
s('A Fair Price for a Repair','Mara asks Jorge to account for more than replacement iron.',[i('smelt','iron_ingot',8)],'mara','the repair price','Count inspection, fitting, and testing. Hiding labor makes a price look kind while asking the craftsperson to donate the missing hours.','Quotes separate materials and labor.'),
s('The Delivery That Must Wait','Fen refuses an unsafe departure. Jorge must explain the delay.',[i('craft','barrel',2)],'fen','the delayed shop delivery','Publish the reason, next update, and option to cancel. I sail when the route is safe enough, not when an angry notice makes waiting uncomfortable.','The notice offers a refund or a dated update.'),
s('Credit without a Public Story','Rowan requests small emergency advances with private applications.',[i('collect','emerald',16)],'rowan','the emergency-credit record','Publish rules and the fund balance. Keep applications private and provide a way to challenge refusal. Inspect decisions without exposing applicants.','The fund opens under short, published terms.'),
s('The Apprentice Checks the Till','Tamsin reports an apprentice skipping breaks to balance every coin.',[i('craft','clock')],'tamsin','the apprentice\'s closing shift','Give the handover a time limit and second checker. A discrepancy can wait for rested eyes; exhaustion is not an accounting method.','Jorge adds a shared closing check and paid break.'),
s('A Shop That Keeps Its Word','Elian reviews disputed sales at Jorge\'s request.',[i('craft','writable_book',2)],'elian','the disputed shop sale','Hear both accounts, inspect receipts, and explain the decision. Leave a route for review. Calling someone dishonest should not be the first tool used.','Jorge posts refund and complaint terms beside the prices.')])

RETROFITS=[
('ac_m03','tamsin','the empty granary','The supplies will reach the kitchen. Ask who could not come to collect them; hunger often stays behind the door that opens least.'),
('ac_m04','mara','the missing forge','These supplies will build a working forge. The first tools go to repairs and planting. People need reasons to stay as well as weapons to defend them.'),
('ac_m06','rowan','the first common hearth','Every household has room in the ledger, including those on the road. A common hearth lets newcomers approach without an introduction.'),
('ac_m08','elian','the cleared roadblock','I will assign a returning patrol before declaring the road open. Travelers deserve more than yesterday\'s victory.'),
('ac_m10','sera','the collector\'s records','These entries explain what was taken, not what was owed. Keep that distinction in the account you take to Eldara.'),
('ac_m12','sera','the debt in ink','Several families signed under threat. The circumstances belong beside the promises; signatures are not the whole story.'),
('ac_m14','mara','the first ward','The fitting holds in a simple test. Tell Eldara what we tested and what remains uncertain. A prototype is a beginning.'),
('ac_m16','tamsin','the counted graves','Numbers help organize care. Families also need names and somewhere to ask questions. Bring both kinds of record.'),
('ac_m18','elian','the end of borrowed peace','The watch is ready. We must also decide how residents can question orders given in their name.'),
('ac_m20','ysolde','the shepherd\'s giant','Protect the threatened people and record the harm. A frightened village deserves both practical help and an honest explanation.'),
('ac_m22','sera','the red witness','The account stays beside what we can verify. Neither certainty nor disbelief should be added to simplify the story.'),
('ac_m24','mara','the cinder gate','Check the return route before trusting the threshold. A way in is half the equipment needed for an expedition.'),
('ac_m26','rowan','the dead kingdom\'s fuel','Reserve what the living settlement needs first. Rebuilding one promise must not quietly break another.'),
('ac_m28','mara','the furnace\'s eye','We can examine the mechanism without restoring its old purpose. Inventory its dangerous parts carefully.'),
('ac_m30','sera','the names in the cinders','Copy legible names and mark uncertain letters. A guess must not become someone\'s identity because readers cannot see our doubt.'),
('ac_m32','tamsin','the record of the dead','Let families decide what belongs in public. Remembering someone does not give us every detail of their life.'),
('ac_m34','rowan','what the crown left behind','Useful buildings may remain. The old claims of obedience do not become ours because we hold their keys.'),
('ac_m36','iona','the sky without dawn','The return route and conflicting readings are marked. Take both the map and its warnings to Eldara.'),
('hc_signal01','sera','the impossible letter','The handwriting resembles yours. That is evidence about the letter, not proof of its account. Compare paper and events separately.'),
('hc_ledger01','rowan','the account that never closes','An account demanding a final balance from living people can always invent another debt. Find the rule that lets someone leave.'),
('hc_forge01','mara','the old workshop chest','These tools served work I no longer choose. Examining them does not excuse the decisions made with them.'),
('hc_crossing01','fen','the missing couriers','Record every last confirmed stop. Similar disappearances may share a cause; do not force agreement by omitting differences.'),
('hc_auditor01','sera','the audience without a throne','Preserve the refusals as well as the answers. A system calling every objection a missing entry cannot hear what we actually said.'),
('hc_home06','rowan','the open chronicle','The household work continues. A river district outside our delivery lists has sent a petition. Bring it to Eldara when you are ready for another journey.'),
('ac_forge01','jorge','the apprentice\'s supplies','Separate materials and training costs. The apprentice should know what is purchased and what the workshop promises to teach.'),
('ac_forge03','rowan','the unmarked metal','Public stock needs a public account. Record where it goes so nobody can later claim it was a private gift.'),
('ac_forge06','elian','the open workshop','The watch will use the same repair queue. An open workshop should not become a barracks annex whenever I arrive.'),
('ac_college01','rowan','the unapproved books','Preserve the questions rulers disliked where readers can find them. Add context rather than a newly forbidden shelf.'),
('ac_college03','mara','the stronger binding','Reinforce the spine but let the book open flat. A binding should survive use, not discourage it.'),
('ac_college06','iona','the keeper\'s questions','Keep a route from conclusions to evidence. Readers should see where another road was possible.'),
('ac_steward01','tamsin','the harvest account','Keep household need and seed visible before counting surplus. A full store matters little if next year\'s planting is called spare.'),
('ac_steward03','fen','the arriving supplies','Give crates a place and dated receipt. Someone should find them without first finding the steward.'),
('ac_steward06','sera','the ordinary stewardship record','Record routine repairs and answered complaints. The absence of crisis can hide the work that prevented it.'),
('ac_atlas01','sera','the blank atlas','A blank page means its compiler lacks an account. It does not mean nobody lives there.'),
('ac_atlas03','fen','the ocean route','Mark landings and conditions for turning back. A useful voyage includes a return plan.'),
('ac_atlas06','rowan','the free-road atlas','Copies remain available without travel permits. Information about public roads should help people use them.'),
('ac_harbor01','mara','the shipwright\'s proposal','Inspect the frame before choosing the finish. A boat succeeds by bringing people home, not by looking complete at launch.'),
('ac_harbor03','iona','the light in the current','Test from the difficult approach. The traveler who most needs a beacon should be able to see it.'),
('ac_harbor06','rowan','the open-coast rules','Publish fees and appeal rights. An open coast cannot hide a different private demand at every landing.'),
('ac_garden01','rowan','the common garden soil','The garden has a clear land agreement. Its keeper should not learn at harvest that the plot was promised elsewhere.'),
('ac_garden03','sera','the healer\'s trial notes','Keep observations and limits together. One personal account cannot promise the same outcome for everyone.'),
('ac_garden06','elian','the garden handover','The watch has contact details and clear paths. Tamsin can close without becoming permanently on call.'),
('ac_sky01','tamsin','the egg\'s care plan','Plan food, space, and rest before celebrating. A future life needs preparation more than an impressive promise.'),
('ac_sky03','fen','the patient shoreline','We will keep this stretch quiet and redirect boats. Patience is easier when the harbor makes room for it.'),
('ac_sky06','iona','the living-sky routes','Mark nests and clear approaches. Maps can support respectful distance instead of turning every discovery into a destination.'),
('ac_watch01','rowan','the watch\'s own rules','Give people outside the watch a complaint route. Authority cannot be its own only witness.'),
('ac_watch03','sera','the lowered colors','Preserve the banners with an honest account. Recording their history differs from asking people to march behind them.'),
('ac_watch06','mara','the marshal\'s equipment','Equipment remains common stock, issued by duty and returned for repair. Keep it that way if the title starts to resemble a crown.')]

FACTIONS=dict(rowan='Dawnstead',sera='Archivists',mara='Hearthwrights',elian='Free Watch',iona='Wayfarers',tamsin='Dawnstead',fen='Wayfarers',ysolde='Wayfarers',caelen='Free Watch',jorge='Dawnstead')
def expand_campaign(quests):
    existing={q['id']:q for q in quests}
    assert len(existing)==385 and len(RETROFITS)==48
    for id,npc,subject,response in RETROFITS:
        q=existing[id]
        q['objectives'].append(t(npc,subject,response))
        q['story']+='\n\nBefore returning to '+q['giver'].title()+', discuss '+subject+' with '+npc.replace('_',' ').title()+'. Complete the earlier objectives before this conversation.'
    previous='hc_home06'
    main_added=[]
    for book,code,section,entries,choices in BOOKS:
        for num,(title,story,work,conversations,after) in enumerate(entries,1):
            id=f'{code}{num:02}'
            deps={1:[previous],2:[f'{code}01'],3:[f'{code}01'],4:[f'{code}02',f'{code}03'],5:[f'{code}04'],6:[f'{code}05']}[num]
            quests.append(dict(id=id,title=title,chapter=book,section=section,story=story+'\n\nComplete the objectives in the order shown. Discuss each named topic with the specified NPC, then report to Eldara.',aftermath=after,icon='minecraft:writable_book',requires=deps,objectives=work+conversations,rewards=[],emeralds=24+num*2,xp=140+num*10,faction='Dawnstead',standing=10,cooldown=0,choices=choices if num==6 else [],giver='eldara'))
            main_added.append(id)
        previous=f'{code}06'
    side_added=[]
    for owner,section,entries in SIDE:
        for num,(title,story,work,conversations,after) in enumerate(entries,1):
            id=f'ns_{owner}{num:02}'
            quests.append(dict(id=id,title=title,chapter='Companion Chronicles | The Work Between Journeys',section=owner.title()+' | '+section,story=story+'\n\nAccept this quest from '+owner.title()+', complete its objectives, then return to '+owner.title()+' with the report.',aftermath=after,icon='minecraft:book',requires=['ac_m06'] if num==1 else [f'ns_{owner}{num-1:02}'],objectives=work+conversations,rewards=[],emeralds=8+num,xp=60+num*5,faction=FACTIONS[owner],standing=5,cooldown=0,choices=[],giver=owner))
            side_added.append(id)
    assert len(main_added)==96 and len(side_added)==76
    return dict(total=len(quests),main_added=len(main_added),side_added=len(side_added),existing_quests_with_new_conversations=len(RETROFITS),main_quests=sum(q['giver']=='eldara' for q in quests),side_quests=sum(q['giver']!='eldara' for q in quests),talk_objectives=sum(o['type']=='talk' for q in quests for o in q['objectives']),quests_with_conversations=sum(any(o['type']=='talk' for o in q['objectives']) for q in quests),conversation_targets=dict(Counter(o['target'] for q in quests for o in q['objectives'] if o['type']=='talk')),new_main_ids=main_added,new_side_ids=side_added,retrofitted_ids=[v[0] for v in RETROFITS],finale=previous)

